Result<Nothing> Connection::end_write() {
  if (PQputCopyEnd(conn_.get(), NULL) == -1) {
    return error(PQerrorMessage(conn_.get()));
  }
  const auto res = PQgetResult(conn_.get());
  if (PQresultStatus(res) != PGRES_COMMAND_OK) {
    return error(PQerrorMessage(conn_.get()));
  }
  return Nothing{};
}

