        [](auto&& _it) { return Iterator<ValueType>(std::move(_it)); }));
  }

  Result<Nothing> rollback() noexcept;

  std::string to_sql(const dynamic::Statement& _stmt) noexcept {
    return sqlite::to_sql_impl(_stmt);
  }

