Result<Nothing> Connection::end_write() {
  if (!stmt_) {
    return error(
        " You need to call .start_write(...) before you can call "
        ".end_write().");
  }
  stmt_ = nullptr;
  return commit().or_else([&](const auto& err) -> Result<Nothing> {
    rollback();
    return error(err.what());
  });
}

